"""Derive SkyyRebirth/build_skyyrebirth_0.5.2.py from SkyyRebirth 0.5.1 (build_skyyrebirth_0.5.1.py = the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_5_1_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on a
copy and compared with 0.5.1 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/rebirth_0_5_2_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.5.2.py   (never --deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.5.2.py
Round cls060 (research/Combat-Into-Class-Spec.md R4; with SkyyTrees 0.6.0 + SkyyClasses 0.1.47 + SkyySkills 0.4.64 - deploy together).
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.5.2 (2026-10-23) = COMBAT INTO CLASS, the SkyyRebirth part (research/Combat-Into-Class-Spec.md R4; deploys + rolls back TOGETHER with
  SkyyTrees 0.6.0, SkyyClasses 0.1.47, SkyySkills 0.4.64). Skyy (docs/answered/classes.md 2026-10-23): "Fold the Combat skill into the class:
  class level is your combat level, move the Combat tree's useful upgrades into the class trees, and retire the separate Combat skill (keep
  XP / no one loses progress)." Q7 (spec default): Combat Echo moves onto the Nexus Class arm (same node, same VP).
  1. THE NEXUS: the Combat arm is gone (10 arms); its Combat Echo is the Class arm's second node, named KILL ECHO (saved key Combat.echo,
     costs, nexus.skillEcho and the reader unchanged - nothing to refund, no power change). The map searches its layout again (10 arms).
  2. Head Start's text says the class tree gets it twice (SkyyTrees 0.6.0 class.headStartX: the class tree replaces the class + Combat trees).
  3. The rail's Adventure row opens /tree acrobatics (the Adventure page has no Combat tree any more; /tree combat = the class tree).
  SAVED DATA: none. ROLLBACK to 0.5.1: safe on its own data (the Combat arm comes back with the same ranks); roll back with the set.
'''

P = G.Patch(os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.5.1.py"), os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.5.2.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.5.1"') and not P.has("0.5.2 (2026-10-23)"), "not the generated SkyyRebirth 0.5.1 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass(")

P.rep('''"""SkyyRebirth 0.5.1 - build script (javassist via jpype). GENERATED by tools/rebirth_0_5_1_patch.py from build_skyyrebirth_0.5.0.py - edit the
patch, never this file. Run: python SkyyRebirth/build_skyyrebirth_0.5.1.py -> SkyyRebirth/SkyyRebirth-0.5.1.jar (no --deploy).
Check: python SkyyRebirth/test_skyyrebirth_0.5.1.py''', '''"""SkyyRebirth 0.5.2 - build script (javassist via jpype). GENERATED by tools/rebirth_0_5_2_patch.py from build_skyyrebirth_0.5.1.py - edit the
patch, never this file. Run: python SkyyRebirth/build_skyyrebirth_0.5.2.py -> SkyyRebirth/SkyyRebirth-0.5.2.jar (no --deploy).
Check: python SkyyRebirth/test_skyyrebirth_0.5.2.py
''' + NOTE + '''
SkyyRebirth 0.5.1 - GENERATED by tools/rebirth_0_5_1_patch.py from build_skyyrebirth_0.5.0.py (the notes below are its own).''')
P.rep('VERSION = "0.5.1"', 'VERSION = "0.5.2"')

# 1. Combat Echo = the Class arm's Kill Echo (same key / costs / reader); the Combat arm leaves the map
P.rep('''tnode("Combat.echo", "Combat Echo", "Combat", 4, 5, 1, 2, "+{v} % Combat XP (kills)", "on the class XP you get for kills",
      reader=("SkyySkills", "xp.combat", _S56))''', '''tnode("Combat.echo", "Kill Echo", "Kills", 4, 5, 1, 2, "+{v} % class XP from kills", "on the class XP you get for kills (it sits on the Class arm since 0.5.2)",
      reader=("SkyySkills", "xp.combat", _S56))   # 0.5.2: Combat folded into the class - same saved key, costs and reader''')
P.rep('''RM_ARMS = [("Class", "Class.echo", ()), ("Mining", "Mining.echo", ("Mining.tool", "Mining.tool2")),
           ("Foraging", "Foraging.echo", ("Foraging.tool", "Foraging.tool2")), ("Combat", "Combat.echo", ()),
           ("Beastmastery", "Beast.echo", ()),''', '''RM_ARMS = [("Class", "Class.echo", ("Combat.echo",)), ("Mining", "Mining.echo", ("Mining.tool", "Mining.tool2")),   # 0.5.2: Kill Echo on the Class arm
           ("Foraging", "Foraging.echo", ("Foraging.tool", "Foraging.tool2")),
           ("Beastmastery", "Beast.echo", ()),''')
P.rep('''  this.pt[2] = "Class Echo +" + @PKG@.RbCfg.num(@PKG@.RbTree.echo(p, @PKG@.RbTree.I_CLASS)) + ", Combat Echo +" + @PKG@.RbCfg.num(@PKG@.RbTree.echo(p, @PKG@.RbTree.I_COMBAT)) + " %";''',
      '''  this.pt[2] = "Class Echo +" + @PKG@.RbCfg.num(@PKG@.RbTree.echo(p, @PKG@.RbTree.I_CLASS)) + ", Kill Echo +" + @PKG@.RbCfg.num(@PKG@.RbTree.echo(p, @PKG@.RbTree.I_COMBAT)) + " %";   // 0.5.2''')
# 2. Head Start: the class tree gets it twice
P.rep('''tnode("Void.head", "Head Start", "Head Start", 0, 3, 2, 3, "+{v} skill points each run", "at the start of each run",''',
      '''tnode("Void.head", "Head Start", "Head Start", 0, 3, 2, 3, "+{v} skill points each run", "at the start of each run in every tree (the class tree twice)",''')
# 3. the Adventure rail row
P.rep('''RM_RAIL = [("Gathering", "tree mining"), ("Crafting", "tree smithing"), ("Adventure", "tree combat"), ("Class", "tree class")]''',
      '''RM_RAIL = [("Gathering", "tree mining"), ("Crafting", "tree smithing"), ("Adventure", "tree acrobatics"), ("Class", "tree class")]   # 0.5.2: no Combat page''')
P.rep('''    String c = q == 0 ? "tree mining" : (q == 1 ? "tree smithing" : (q == 2 ? "tree combat" : "tree class"));''',
      '''    String c = q == 0 ? "tree mining" : (q == 1 ? "tree smithing" : (q == 2 ? "tree acrobatics" : "tree class"));   // 0.5.2''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0
P.finish()
